(function(){
'use strict';
const $=id=>document.getElementById(id),catalogKey='declic-library-v1',builtins=DEClic_BUILTINS;
let custom=[],storageIssue=false,deleteTarget=null,uid=0,recoveryRaw=null,builderDescription='',persistError='';
function readCatalog(){
 const raw=localStorage.getItem(catalogKey);if(raw===null)return {quizzes:[],damaged:null};
 let parsed;try{parsed=JSON.parse(raw);}catch{return {quizzes:[],damaged:raw};}
 if(!Array.isArray(parsed))return {quizzes:[],damaged:raw};
 const quizzes=[],ids=new Set();let damaged=parsed.length>50;
 for(const q of parsed.slice(0,50)){
  try{if(!q||typeof q.id!=='string'||!/^custom-[a-zA-Z0-9_-]{1,100}$/.test(q.id)||ids.has(q.id))throw new Error();
   const normalized=QuizCatalog.normalizeQuiz(q);ids.add(q.id);quizzes.push({...normalized,id:q.id,storageKey:'declic-'+q.id+'-v1',symbol:normalized.title.slice(0,1).toUpperCase(),custom:true});
  }catch{damaged=true;}
 }
 return {quizzes,damaged:damaged?raw:null};
}
try{const saved=readCatalog();custom=saved.quizzes;recoveryRaw=saved.damaged;storageIssue=recoveryRaw!==null;}catch{storageIssue=true;}
const all=()=>[...builtins,...custom];
const searchable=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr');
function notify(message,error=false){$('library-message').textContent=message;$('library-message').classList.toggle('error',error);}
function persist(update){persistError='';try{
 const latest=readCatalog();
 const next=update(latest.quizzes);
 if(latest.damaged!==null){
  const backupKey=catalogKey+'-recovery';const previous=localStorage.getItem(backupKey);
  if(previous!==null&&previous!==latest.damaged)localStorage.setItem(backupKey+'-'+Date.now(),previous);
  localStorage.setItem(backupKey,latest.damaged);recoveryRaw=latest.damaged;
 }
 localStorage.setItem(catalogKey,JSON.stringify(next));custom=next;storageIssue=false;return true;
 }catch(error){persistError=error.message&&error.message.startsWith('Tu peux')?error.message:'Le navigateur ne permet pas d’enregistrer ce quiz. Aucune donnée existante n’a été remplacée. Libère de l’espace, puis réessaie.';notify(persistError,true);return false;}
}
function node(tag,className,text){const e=document.createElement(tag);if(className)e.className=className;if(text!==undefined)e.textContent=text;return e;}
function download(quiz){const blob=new Blob([JSON.stringify({title:quiz.title,description:quiz.description,cards:quiz.cards},null,2)],{type:'application/json;charset=utf-8'});const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=quiz.title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').toLowerCase()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Quiz exporté. Tu peux l’importer sur un autre appareil. La progression reste propre à ce navigateur.');}
function renderLibrary(){const quizzes=all(),query=searchable($('quiz-search').value.trim());$('library-count').textContent=quizzes.length+' matières · '+quizzes.reduce((n,q)=>n+q.cards.length,0)+' questions';const container=$('quiz-list');container.replaceChildren();let visible=0;
 for(const q of quizzes){if(!searchable(q.title).includes(query))continue;visible++;const mastered=DeclicQuiz.progress(q),pct=Math.round(mastered/q.cards.length*100);const article=node('article','subject-card'),top=node('div','subject-top'),symbol=node('span','subject-symbol',q.symbol||q.title[0]);symbol.setAttribute('aria-hidden','true');top.append(symbol,node('span','subject-kind',q.custom?'PERSONNEL':'COURS'));article.appendChild(top);const h=node('h2','',q.title);article.append(h,node('p','subject-description',q.description));article.append(node('p','subject-meta',q.cards.length+' questions · '+new Set(q.cards.map(c=>c.chapter)).size+' chapitres'));const meter=node('div','subject-meter');meter.setAttribute('role','progressbar');meter.setAttribute('aria-label','Progression en '+q.title);meter.setAttribute('aria-valuemin','0');meter.setAttribute('aria-valuemax','100');meter.setAttribute('aria-valuenow',String(pct));const fill=node('div');fill.style.width=pct+'%';meter.appendChild(fill);article.append(meter,node('p','subject-progress',mastered+' / '+q.cards.length+' réussies · '+pct+' %'));
 const actions=node('div','subject-actions'),start=node('button','btn primary',mastered?'Continuer ↗':'Réviser ↗');start.type='button';start.setAttribute('aria-label','Réviser '+q.title);start.onclick=()=>openQuiz(q.id);const exportBtn=node('button','text-btn','Exporter');exportBtn.type='button';exportBtn.setAttribute('aria-label','Exporter '+q.title);exportBtn.onclick=()=>download(q);actions.append(start,exportBtn);if(globalThis.DeclicCourses&&DeclicCourses.available(q)){const read=node('button','text-btn','Voir le cours');read.type='button';read.setAttribute('aria-label','Voir le cours de '+q.title);read.onclick=()=>DeclicCourses.open(q);actions.appendChild(read);}if(q.custom){const del=node('button','text-btn delete-btn','Supprimer');del.type='button';del.setAttribute('aria-label','Supprimer '+q.title);del.onclick=()=>{deleteTarget=q;$('delete-name').textContent=q.title;$('delete-dialog').showModal();};actions.appendChild(del);}article.appendChild(actions);container.appendChild(article);}
 $('no-results').classList.toggle('hidden',visible!==0);if(!query){const add=node('button','add-subject'),plus=node('span','add-plus','+');add.type='button';add.append(plus,node('strong','','Une nouvelle matière'),node('span','','Ajoute tes questions et leurs corrections'));add.onclick=()=>openBuilder();container.appendChild(add);}
}
function showLibrary(){DeclicQuiz.leave();$('quiz-screen').classList.add('hidden');$('course-screen')?.classList.add('hidden');$('library-screen').classList.remove('hidden');$('home-button').classList.add('hidden');document.title='Déclic · Mes quiz';renderLibrary();$('library-title').focus();}
function openQuiz(id){const quiz=all().find(q=>q.id===id);if(!quiz)return;$('library-screen').classList.add('hidden');$('quiz-screen').classList.remove('hidden');$('home-button').classList.remove('hidden');DeclicQuiz.open(quiz);$('quiz-subject').focus();window.scrollTo({top:0,behavior:'smooth'});}
function addRow(card={}){const row=node('fieldset','question-row'),num=++uid;row.dataset.cardId=card.id||'';row._sources=card.sources||[];row.appendChild(node('legend','','Question '+($('question-rows').children.length+1)));
 for(const [name,label,type,value] of [['question','Question','textarea',card.question||''],['answer','Correction attendue','textarea',card.answer||''],['chapter','Chapitre (facultatif)','input',card.chapter||'']]){const field=node('div','builder-field'),l=node('label','',label),input=node(type);input.id='edit-'+name+'-'+num;input.dataset.field=name;input.value=value;if(type==='textarea'){input.rows=name==='question'?2:3;input.maxLength=name==='question'?10000:40000;}else{input.type='text';input.maxLength=150;}l.htmlFor=input.id;field.append(l,input);row.appendChild(field);}
 const remove=node('button','text-btn','Retirer cette question');remove.type='button';remove.onclick=()=>{row.remove();if(!$('question-rows').children.length)addRow();Array.from($('question-rows').children).forEach((r,i)=>r.querySelector('legend').textContent='Question '+(i+1));};row.appendChild(remove);$('question-rows').appendChild(row);return row;}
function openBuilder(data){builderDescription=data?.description||'';$('builder-title').value=data?.title||'';$('builder-error').textContent='';$('question-rows').replaceChildren();uid=0;for(const card of data?.cards||[{}])addRow(card);$('builder-dialog').showModal();$('builder-title').focus();}
function saveBuilder(e){e.preventDefault();if(!$('builder-dialog').open)return;try{const rows=Array.from($('question-rows').children).map(row=>({...Object.fromEntries(Array.from(row.querySelectorAll('[data-field]')).map(input=>[input.dataset.field,input.value])),...(row.dataset.cardId?{id:row.dataset.cardId}:{}),...(row._sources.length?{sources:row._sources}:{})})).filter(c=>c.question.trim()||c.answer.trim());const parsed=QuizCatalog.normalizeQuiz({title:$('builder-title').value,...(builderDescription?{description:builderDescription}:{}),cards:rows});const id='custom-'+crypto.randomUUID(),quiz={...parsed,id,storageKey:'declic-'+id+'-v1',symbol:parsed.title[0].toUpperCase(),custom:true};if(!persist(latest=>{if(latest.length>=50)throw new Error('Tu peux ajouter jusqu’à 50 quiz personnels. Exporte puis retire un ancien quiz pour en ajouter un autre.');return [...latest,quiz];})){$('builder-error').textContent=persistError||'Enregistrement impossible : vérifie l’espace disponible dans ton navigateur.';return;}$('builder-dialog').close();$('quiz-search').value='';renderLibrary();notify('« '+quiz.title+' » a été ajouté à ta bibliothèque.');}catch(error){$('builder-error').textContent=error.message;}}
async function importFile(){const file=$('import-file').files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('Le fichier est trop volumineux (5 Mo maximum).');let data;try{data=JSON.parse(await file.text());}catch{throw new Error('Ce fichier ne contient pas un quiz JSON valide. Utilise un fichier exporté depuis Déclic.');}const quiz=QuizCatalog.normalizeQuiz(data,file.name.replace(/\.json$/i,''));openBuilder(quiz);}catch(error){notify(error.message,true);}finally{$('import-file').value='';}}
$('home-button').onclick=showLibrary;$('add-quiz').onclick=()=>openBuilder();$('quiz-search').addEventListener('input',renderLibrary);$('import-quiz').onclick=()=>$('import-file').click();$('import-file').addEventListener('change',importFile);$('add-question').onclick=()=>{const row=addRow();row.scrollIntoView({behavior:'smooth',block:'nearest'});row.querySelector('textarea').focus();};$('builder-form').addEventListener('submit',saveBuilder);$('cancel-builder').onclick=()=>$('builder-dialog').close();$('cancel-delete').onclick=()=>$('delete-dialog').close();$('confirm-delete').onclick=()=>{if(deleteTarget&&persist(latest=>latest.filter(q=>q.id!==deleteTarget.id))){try{localStorage.removeItem(deleteTarget.storageKey);}catch{}$('delete-dialog').close();deleteTarget=null;renderLibrary();notify('Le quiz personnel a été supprimé.');}};
window.addEventListener('storage',event=>{if(event.key!==catalogKey)return;try{const latest=readCatalog();custom=latest.quizzes;recoveryRaw=latest.damaged;renderLibrary();notify('Ta bibliothèque a été mise à jour depuis un autre onglet.');}catch{notify('La bibliothèque est temporairement inaccessible. Tes quiz ouverts restent disponibles.',true);}});
window.addEventListener('declic:progress',()=>{if(!$('library-screen').classList.contains('hidden'))renderLibrary();});
renderLibrary();if(storageIssue)notify('Une sauvegarde est endommagée ou inaccessible. Les quiz récupérables sont affichés ; une copie sera conservée avant tout nouvel enregistrement.',true);
globalThis.DeclicLibrary={all,openQuiz,showLibrary,renderLibrary,openBuilder};
})();
